-- Default-preserving financial classification. No historical order is reclassified.
ALTER TABLE orders ADD COLUMN order_mode VARCHAR(24) NOT NULL DEFAULT 'CUSTOMER' CHECK(order_mode IN ('CUSTOMER','INTERNAL_SERVICE'));
CREATE TRIGGER service_order_insert_guard BEFORE INSERT ON orders FOR EACH ROW BEGIN IF NEW.order_mode='INTERNAL_SERVICE' AND NEW.status IN ('paid','awaiting_payment') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Internal service orders cannot enter payment'; END IF; END;
CREATE TRIGGER service_order_update_guard BEFORE UPDATE ON orders FOR EACH ROW BEGIN IF NEW.order_mode<>OLD.order_mode OR (NEW.order_mode='INTERNAL_SERVICE' AND NEW.status IN ('paid','awaiting_payment')) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Order financial classification is immutable'; END IF; END;
CREATE TRIGGER service_payment_guard BEFORE INSERT ON payment_confirmations FOR EACH ROW BEGIN IF EXISTS(SELECT 1 FROM orders WHERE order_id=NEW.order_id AND order_mode='INTERNAL_SERVICE') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Nonfinancial order cannot receive payment'; END IF; END;
CREATE TRIGGER service_paid_history_guard BEFORE INSERT ON order_status_history FOR EACH ROW BEGIN IF NEW.status IN ('paid','awaiting_payment') AND EXISTS(SELECT 1 FROM orders WHERE order_id=NEW.order_id AND order_mode='INTERNAL_SERVICE') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Nonfinancial order cannot receive payment history'; END IF; END;
CREATE TRIGGER service_receipt_guard BEFORE INSERT ON print_jobs FOR EACH ROW BEGIN IF EXISTS(SELECT 1 FROM orders WHERE order_id=NEW.order_id AND order_mode='INTERNAL_SERVICE') AND (NEW.job_type<>'STATION_KOT' OR NEW.adapter_type_snapshot<>'virtual') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Nonfinancial orders support virtual station KOT only'; END IF; END;
